svg.script:
const FF_JS = "https:/" + "/cdn.jsdelivr.net/npm/@ffmpeg/ffmpeg@0.11.6/dist/ffmpeg.min.js";
const CORE_JS = "https:/" + "/cdn.jsdelivr.net/npm/@ffmpeg/core-st@0.11.1/dist/ffmpeg-core.js";
const frame = document.getElementById("linux_frame");

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"/>
<style>
  body,html{margin:0;padding:0;background:#000;color:#eee;font-family:monospace;height:100%;display:flex;flex-direction:column;overflow:hidden}
  #bar{padding:8px;background:#1a1a1a;display:flex;gap:8px;align-items:center;border-bottom:1px solid #333;font-size:12px}
  #cv{flex:1;width:100%;height:100%;object-fit:contain;background:#000}
  #msg{margin-left:auto;color:#7f7}
</style>
<script>
  const OrigWorker = window.Worker;
  window.Worker = function(url, opts) {
    const blob = new Blob(['importScripts("' + url + '");'], { type: "application/javascript" });
    return new OrigWorker(URL.createObjectURL(blob), opts);
  };
<\/script>
<script src="${FF_JS}"><\/script>
</head><body>
<div id="bar">
  <input type="file" id="f" accept=".mkv,.webm,.mp4" disabled />
  <button id="btn">Pause</button>
  <span id="msg">Loading FFmpeg-ST software decoder...</span>
</div>
<canvas id="cv"></canvas>
<script>
  const cv = document.getElementById("cv"), ctx = cv.getContext("2d");
  const msg = document.getElementById("msg"), fileIn = document.getElementById("f");
  let play = true, running = false, ffmpeg = null, actx = null;

  document.getElementById("btn").onclick = async () => {
    play = !play;
    document.getElementById("btn").textContent = play ? "Pause" : "Play";
    if (actx) {
      if (play && actx.state === "suspended") await actx.resume();
      else if (!play && actx.state === "running") await actx.suspend();
    }
  };

  (async () => {
    try {
      const { createFFmpeg } = FFmpeg;
      ffmpeg = createFFmpeg({
        corePath: "${CORE_JS}",
        mainName: "main",
        log: false
      });
      await ffmpeg.load();
      fileIn.disabled = false;
      msg.textContent = "FFmpeg-ST SW Ready (Video + Audio)";
    } catch (e) {
      msg.textContent = "Load ERR: " + e.message;
    }
  })();

  function findFirstCluster(u8) {
    for (let i = 0; i < u8.length - 4; i++) {
      if (u8[i] === 0x1F && u8[i + 1] === 0x43 && u8[i + 2] === 0xB6 && u8[i + 3] === 0x75) {
        return i;
      }
    }
    return Math.min(65536, u8.length);
  }

  function scheduleAudio(pcmBytes) {
    if (!pcmBytes || pcmBytes.byteLength < 8) return 0;
    if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 44100 });
    if (actx.state === "suspended" && play) actx.resume();

    const samples = Math.floor(pcmBytes.byteLength / 8); // stereo float32 (2 ch * 4 bytes)
    const f32 = new Float32Array(pcmBytes.buffer, pcmBytes.byteOffset, samples * 2);
    const abuf = actx.createBuffer(2, samples, 44100);
    const L = abuf.getChannelData(0), R = abuf.getChannelData(1);
    for (let i = 0; i < samples; i++) {
      L[i] = f32[i * 2];
      R[i] = f32[i * 2 + 1];
    }
    const src = actx.createBufferSource();
    src.buffer = abuf;
    src.connect(actx.destination);
    src.start(actx.currentTime + 0.05);
    return abuf.duration;
  }

  fileIn.onchange = async (e) => {
    const file = e.target.files ? e.target.files.item(0) : null;
    if (!file || !ffmpeg) return;
    running = false;
    await new Promise(r => setTimeout(r, 80));
    running = true;
    play = true;
    document.getElementById("btn").textContent = "Pause";
    if (!actx) actx = new (window.AudioContext || window.webkitAudioContext)({ sampleRate: 44100 });

    // Read the first 512 KB to extract the exact EBML + Segment + Tracks header
    const headProbe = new Uint8Array(await file.slice(0, 524288).arrayBuffer());
    const hdrLen = findFirstCluster(headProbe);
    const mkvHeader = headProbe.subarray(0, hdrLen);

    const W = 640, H = 360;
    cv.width = W; cv.height = H;
    const imgData = ctx.createImageData(W, H);
    const SLICE_BYTES = 8 * 1024 * 1024;
    let offset = hdrLen, drawn = 0;

    while (running && offset < file.size) {
      if (!play) { await new Promise(r => setTimeout(r, 50)); continue; }
      const pct = ((offset / file.size) * 100).toFixed(1);
      msg.textContent = "Decoding chunk @ " + pct + "%...";

      const bodyBuf = new Uint8Array(await file.slice(offset, offset + SLICE_BYTES).arrayBuffer());
      const combined = new Uint8Array(mkvHeader.length + bodyBuf.length);
      combined.set(mkvHeader, 0);
      combined.set(bodyBuf, mkvHeader.length);

      try { ffmpeg.FS("unlink", "part.mkv"); } catch (_) {}
      ffmpeg.FS("writeFile", "part.mkv", combined);

      try {
        await ffmpeg.run(
          "-err_detect", "ignore_err", "-i", "part.mkv",
          "-sn",
          "-map", "0:v:0", "-vf", "scale=" + W + ":" + H, "-r", "24", "-f", "rawvideo", "-pix_fmt", "rgba", "out.rgba",
          "-map", "0:a:0?", "-ac", "2", "-ar", "44100", "-f", "f32le", "out.pcm"
        );
      } catch (_) {}

      try { ffmpeg.FS("unlink", "part.mkv"); } catch (_) {}

      let raw = null, pcm = null;
      try { raw = ffmpeg.FS("readFile", "out.rgba"); } catch (_) {}
      try { pcm = ffmpeg.FS("readFile", "out.pcm"); } catch (_) {}
      try { ffmpeg.FS("unlink", "out.rgba"); } catch (_) {}
      try { ffmpeg.FS("unlink", "out.pcm"); } catch (_) {}

      const frameBytes = W * H * 4;
      const total = raw ? Math.floor(raw.length / frameBytes) : 0;

      if (total > 0) {
        const audioDur = scheduleAudio(pcm);
        const frameDelay = audioDur > 0 ? Math.max(20, (audioDur * 1000) / total) : 41;

        for (let i = 0; i < total && running; i++) {
          while (!play && running) await new Promise(r => setTimeout(r, 50));
          imgData.data.set(raw.subarray(i * frameBytes, (i + 1) * frameBytes));
          ctx.putImageData(imgData, 0, 0);
          drawn++;
          if (drawn % 4 === 1) msg.textContent = "Playing (" + pct + "%) | Frame " + drawn + (audioDur > 0 ? " | Audio ON" : "");
          await new Promise(r => setTimeout(r, frameDelay));
        }
      }
      offset += SLICE_BYTES;
    }
    if (running) msg.textContent = "Finished (" + drawn + " frames)";
  };
<\/script></body></html>`;

const doc = frame.contentDocument || frame.contentWindow.document;
doc.open(); doc.write(html); doc.close();
